import json,statistics as st
def load(n):
    d=json.load(open(n+'.json')); return {e['example_id']:e for e in d['examples']}, d
a,da=load('r6-01-curve'); b,_=load('r5-02-curve'); c,_=load('r2-04-curve'); r1,_=load('r5-01-curve')
print(len(a), da['metrics'])
ts=[e['resources']['solver']['wall_seconds'] for e in a.values()]
print('solve median',st.median(ts),'mean',st.mean(ts),'max',max(ts))
for nm,o in (('r5-02',b),('r2-04',c),('r5-01',r1)):
    w=sum(a[k]['score']>o[k]['score'] for k in a); l=sum(a[k]['score']<o[k]['score'] for k in a)
    print(nm,'better/worse',w,l, 'score', sum(e['score'] for e in o.values())/len(o))
print('acc1',st.mean(e['statistics']['acc1'] for e in a.values()),'np3',st.mean(e['statistics']['np3'] for e in a.values()))
meta={}
for l in open('/workspace/case/dataset/train_curve.meta.jsonl'):
    m=json.loads(l); meta[m['id']]=m
by={}
for k,e in a.items(): by.setdefault(meta[k]['style'],[]).append((e['score'],b[k]['score'],c[k]['score']))
